window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2343aa8796f2a8dc"]={"versions": [{"id": "FIG-2343aa8796f2a8dc", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im AUTOSAR-Manifest (Adaptive Platform). Es definiert die Zuordnung zwischen kryptografischen Anforderungen (<code>CryptoNeed</code>) und Service- bzw. Software-Ports (<code>PortPrototype</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>CryptoNeedToPortPrototypeMapping</code> (Stereotyp <code>«ARElement»</code>): Zentrales Mapping-Element zur Verknüpfung von Schnittstellen und Krypto-Bedarfen.</li>\n<li><code>PortPrototype</code> (Stereotypen <code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>): Ziel-Portprototyp der Assoziationsrolle <code>+portPrototype</code>.</li>\n<li><code>CryptoNeed</code> (Stereotypen <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>): Spezifikation der kryptografischen Anforderung mit Attribut:</li>\n<li><code>+ primitiveFamily : String</code></li>\n<li>Assoziationsrolle <code>+cryptoNeed</code> mit Multiplizität <code>1</code>.</li>\n<li>Beziehungen:</li>\n<li>Gerichtete Assoziation von <code>CryptoNeedToPortPrototypeMapping</code> auf <code>PortPrototype</code> über die Rolle <code>+portPrototype</code>.</li>\n<li>Gerichtete Assoziation von <code>CryptoNeedToPortPrototypeMapping</code> auf <code>CryptoNeed</code> über die Rolle <code>+cryptoNeed</code> mit Kardinalität <code>1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Deklarationsmodell zur Entwurfszeit im Manifest. Die Zuordnung verknüpft eine kryptografische Anforderung (<code>CryptoNeed</code>) verbindlich mit einem konkreten <code>PortPrototype</code>, über den kryptografische Operationen oder Datenströme abgewickelt werden. Es liegt kein dynamischer Laufzeit- oder Sequenzablauf vor.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung ist normativ für Manifest-Generatoren und Konfigurationstools der AUTOSAR Adaptive Platform. Eine Instanz von <code>CryptoNeedToPortPrototypeMapping</code> muss exakt einer Instanz von <code>CryptoNeed</code> (<code>[1]</code>) zugeordnet sein, wodurch kryptografische Primitive einer funktionalen Port-Schnittstelle semantisch eindeutig zugewiesen werden.</p>"}, {"id": "FIG-722883a8d7021126", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im AUTOSAR-Manifest (Adaptive Platform). Es definiert die Zuordnung zwischen kryptografischen Anforderungen (<code>CryptoNeed</code>) und Service- bzw. Software-Ports (<code>PortPrototype</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>CryptoNeedToPortPrototypeMapping</code> (Stereotyp <code>«ARElement»</code>): Zentrales Mapping-Element zur Verknüpfung von Schnittstellen und Krypto-Bedarfen.</li>\n<li><code>PortPrototype</code> (Stereotypen <code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>): Ziel-Portprototyp der Assoziationsrolle <code>+portPrototype</code>.</li>\n<li><code>CryptoNeed</code> (Stereotypen <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>): Spezifikation der kryptografischen Anforderung mit Attribut:</li>\n<li><code>+ primitiveFamily : String</code></li>\n<li>Assoziationsrolle <code>+cryptoNeed</code> mit Multiplizität <code>1</code>.</li>\n<li>Beziehungen:</li>\n<li>Gerichtete Assoziation von <code>CryptoNeedToPortPrototypeMapping</code> auf <code>PortPrototype</code> über die Rolle <code>+portPrototype</code>.</li>\n<li>Gerichtete Assoziation von <code>CryptoNeedToPortPrototypeMapping</code> auf <code>CryptoNeed</code> über die Rolle <code>+cryptoNeed</code> mit Kardinalität <code>1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Deklarationsmodell zur Entwurfszeit im Manifest. Die Zuordnung verknüpft eine kryptografische Anforderung (<code>CryptoNeed</code>) verbindlich mit einem konkreten <code>PortPrototype</code>, über den kryptografische Operationen oder Datenströme abgewickelt werden. Es liegt kein dynamischer Laufzeit- oder Sequenzablauf vor.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung ist normativ für Manifest-Generatoren und Konfigurationstools der AUTOSAR Adaptive Platform. Eine Instanz von <code>CryptoNeedToPortPrototypeMapping</code> muss exakt einer Instanz von <code>CryptoNeed</code> (<code>[1]</code>) zugeordnet sein, wodurch kryptografische Primitive einer funktionalen Port-Schnittstelle semantisch eindeutig zugewiesen werden.</p>"}], "trans": [{"from": "FIG-2343aa8796f2a8dc", "to": "FIG-722883a8d7021126", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
